    psx_cyc_step(cpu, 0x80000001u);
#endif
    uint32_t _jt_8001CC08 = cpu->gpr[31];  /* latch indirect target before delay slot */
    /* delay slot (always executes) */
#ifdef PSX_ENABLE_BLOCK_CYCLES
    psx_cyc_step(cpu, 0x1u);
#endif
